data.query:
query Query($where: WorkOrderProcessBomWhereInput, $orderBy: [WorkOrderProcessBomOrderByInput!], $first: Int, $after: String) {
  bom:workOrderProcessBom(where: $where, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {

        componentProductId
        componentProductStrategyProcessId
        componentProductStrategy{consumptionUnitId}
      }
    }
  }
}

data.variablesTransform:
(
	$id := $cuid();
	$h := $state.context.REQUEST.DATA.history;
	$product := $h.productId;
	$bom := bom.edges.node;
	$trx := $state.context.LOCAL.trx;
	$rework := $h.workOrder.workOrderTypeId = "Rework";
	$returnToWorkOrder := $isNilOrEmpty($h.workOrder.orderReference);
	$finalOp := $h.workOrderProcess.final;
	$outsideProcessingNetsuite := $h
		.workOrder
		.integrationData
		.t_outsourced
		= "T";
	$ospCustomData := $outsideProcessingNetsuite
		? ($finalOp
			? {
				"outsourced": true,
				"linkedPoId": $h.workOrder.integrationData.t_linkedpo
			}
			: { "fuuzOnly": true })
		: undefined;
	{
		"p": $h
			.{
				"create": {
					"id": $id,
					"workOrderId": workOrderId,
					"workOrderProcessId": workOrderProcessId,
					"quantity": transactionTypeId = "Production Add"
						? quantity
						: 0,
					"startAt": occurAt,
					/* Checks for rework order type, if true and returning to original workorder mark as fuuzOnly to prevent posting to netsuite
                If rework and not returning to original workorder mark only the final operation as assemblyBuild to allow posting to netsuite
								3/20/2025 adds ospCustomData, if not using osp in netsuite custom data remains undefined, else the linkedPo id is inserted and flagged as outsourced */
					"customData": $rework
						? ($returnToWorkOrder
							? { "fuuzOnly": true }
							: ($finalOp
								? { "assemblyBuild": true }
								: { "fuuzOnly": true }))
						: $ospCustomData
				}
			},
		"pc": $append(
			[
				$bom
					.(
						$cp := componentProductId;
						{
							"create": {
								"id": $id & "-" & $cp,
								"productionAggregationId": $id,
								"quantity": $coalesce([
									$trx[sourceProductId = $cp].sourceQuantity.value
										~> $sum(),
									0
								]),
								"isUsage": true,
								"isLabor": false,
								"isSetup": false,
								"isOverhead": false,
								"workOrderProcessId": $h.workOrderProcessId,
								"componentStrategyProcessId": componentProductStrategyProcessId,
								"componentProductId": componentProductId,
								"componentUnitId": componentProductStrategy
									.consumptionUnitId
							}
						}
					)
			],
			[
				{
					"create": {
						"productionAggregationId": $id,
						"quantity": 0,
						"isUsage": false,
						"isSetup": true,
						"isLabor": true,
						"isOverhead": true,
						"totalSetupHours": $h.actualSetupHours,
						"totalLaborHours": $h.actualLaborHours,
						"totalOverheadHours": $h.actualMachineHours,
						"workOrderProcessId": $h.workOrderProcessId
					}
				}
			]
		),
		"it": $trx
			.{
				"update": { "aggregationId": $id /*& "-" & sourceProductId*/ },
				"where": { "id": id }
			},
		"h": {
			"update": { "aggregationId": $id },
			"where": { "id": $h.id }
		}
	}
)

(
	$h := $state.context.REQUEST.DATA.history;
	$trx := $state.context.LOCAL.trx;
	$agg := $state.context.LOCAL.agg;
	$cmp := $agg.components.edges.node;
	{
		"p": $agg
			.{
				"update": {
					"quantity": ($h.transactionTypeId = "Production Add"
						? $h.quantity
						: 0)
						+ quantity
				},
				"where": { "id": id }
			},
		"pc": $append(
			[
				$cmp[isUsage]
					.(
						$cp := componentProductId;
						{
							"update": {
								"quantity": quantity
									+ $coalesce([
										$trx[sourceProductId = $cp].sourceQuantity.value~>$sum(),
										0
									])
							},
							"where": { "id": id }
						}
					)
			],
			[
				$cmp[isLabor]
					.{
						"update": {
							"quantity": 0,
							"totalSetupHours": $coalesce([totalSetupHours, 0])
								+ $coalesce([$h.actualSetupHours, 0]),
							"totalLaborHours": $coalesce([totalLaborHours, 0])
								+ $coalesce([$h.actualLaborHours, 0]),
							"totalOverheadHours": $coalesce([totalOverheadHours, 0])
								+ $coalesce([$h.actualMachineHours, 0])
						},
						"where": { "id": id }
					}
			]
		),
		"it": $trx
			.{
				"update": {
					"aggregationId": $agg.id & "-" & sourceProductId
				},
				"where": { "id": id }
			},
		"h": {
			"update": { "aggregationId": $agg.id },
			"where": { "id": $h.id }
		}
	}
)

data.query:
query Query(
  $where: ProductionAggregationWhereInput
  $orderBy: [ProductionAggregationOrderByInput!]
  $first: Int
  $after: String
) {
  agg: productionAggregation(
    where: $where
    orderBy: $orderBy
    first: $first
    after: $after
  ) {
    edges {
      node {
        id
        customData
      }
    }
  }
}

query Query($where: ProductionAggregationWhereInput, $whereTrx: InventoryTransactionWhereInput) {
  agg: productionAggregation(where: $where) {
    edges {
      node {
        id
        quantity
        components(where: {isAdjustment: {_eq: false}}) {
          edges {
            node {
              id
              quantity
              totalLaborHours
              totalOverheadHours
              totalSetupHours
              isLabor
              isOverhead
              isSetup
              isUsage
              componentStrategyProcessId
              componentProductId
              workOrderProcessId
            }
          }
        }
      }
    }
  }
  trx: inventoryTransaction(where: $whereTrx) {
    edges {
      node {
        sourceQuantity {
          value
          unitId
        }
        sourceProductId
        id
      }
    }
  }
}

